-- 410: Original BrillaPrep WASSCE Core Mathematics sprint 1 beta questions, part 8 of 8 (batch wassce-core-math-sprint1-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_410_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_410_guard;
INSERT INTO _migration_410_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_043' AND NOT (q.topic_id IS 'topic_wassce_p2_math_num' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Round 3.786 correct to one decimal place.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 3.7","B. 3.79","C. 3.8","D. 4.0"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The second decimal digit is 8, which is at least 5, so the first decimal digit rounds up: 3.786 ≈ 3.8 to one decimal place. Therefore the correct answer is C: 3.8.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Round' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_043' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_410_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_044' AND NOT (q.topic_id IS 'topic_wassce_p2_math_num' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Find the highest common factor (HCF) of 12 and 18.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 3","B. 36","C. 2","D. 6"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The factors of 12 are 1, 2, 3, 4, 6, 12 and the factors of 18 are 1, 2, 3, 6, 9, 18. The largest common factor is 6. (36 is the LCM, not the HCF.) Therefore the correct answer is D: 6.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_044' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_410_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_045' AND NOT (q.topic_id IS 'topic_wassce_p2_math_num' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A trader buys an article for GH₵50.00 and sells it for GH₵65.00. Calculate the percentage profit.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 30%","B. 23.1%","C. 15%","D. 130%"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Profit = 65 − 50 = GH₵15.00. Percentage profit = (profit ÷ cost price) × 100 = (15/50) × 100 = 30%. (23.1% wrongly uses the selling price as the base.) Therefore the correct answer is A: 30%.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_045' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_410_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_046' AND NOT (q.topic_id IS 'topic_wassce_p2_math_num' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Calculate the simple interest on GH₵2,000.00 invested at 5% per annum for 3 years.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. GH₵30.00","B. GH₵300.00","C. GH₵3,000.00","D. GH₵150.00"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Simple interest = PRT/100 = (2,000 × 5 × 3)/100 = 30,000/100 = GH₵300.00. (GH₵150.00 is the interest for one year only.) Therefore the correct answer is B: GH₵300.00.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_046' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_410_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_047' AND NOT (q.topic_id IS 'topic_wassce_p2_math_num' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'An amount of GH₵840.00 is shared between two people in the ratio 3 : 4. Find the larger share.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. GH₵420.00","B. GH₵360.00","C. GH₵480.00","D. GH₵120.00"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Total parts = 3 + 4 = 7, so one part is 840 ÷ 7 = GH₵120.00. The larger share is 4 × 120 = GH₵480.00. (GH₵360.00 is the smaller share.) Therefore the correct answer is C: GH₵480.00.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_047' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_410_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s1_048' AND NOT (q.topic_id IS 'topic_wassce_p2_math_num' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The price of a shirt is increased by 20% and the new price is later decreased by 20%. The final price is what percentage of the original price?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 100%","B. 104%","C. 90%","D. 96%"]' AND q.correct_answer IS 'D' AND q.explanation IS 'After the increase the price is 1.20 times the original; after the decrease it is 1.20 × 0.80 = 0.96 times the original, which is 96%. The two 20% changes do not cancel because they act on different bases. Therefore the correct answer is D: 96%.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s1_048' AND NOT (r.batch_id IS 'wassce-core-math-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s1_043', 'topic_wassce_p2_math_num', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Round 3.786 correct to one decimal place.', 'multiple_choice', NULL, '["A. 3.7","B. 3.79","C. 3.8","D. 4.0"]', 'C', 'The second decimal digit is 8, which is at least 5, so the first decimal digit rounds up: 3.786 ≈ 3.8 to one decimal place. Therefore the correct answer is C: 3.8.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Round', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s1_044', 'topic_wassce_p2_math_num', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Find the highest common factor (HCF) of 12 and 18.', 'multiple_choice', NULL, '["A. 3","B. 36","C. 2","D. 6"]', 'D', 'The factors of 12 are 1, 2, 3, 4, 6, 12 and the factors of 18 are 1, 2, 3, 6, 9, 18. The largest common factor is 6. (36 is the LCM, not the HCF.) Therefore the correct answer is D: 6.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s1_045', 'topic_wassce_p2_math_num', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'A trader buys an article for GH₵50.00 and sells it for GH₵65.00. Calculate the percentage profit.', 'multiple_choice', NULL, '["A. 30%","B. 23.1%","C. 15%","D. 130%"]', 'A', 'Profit = 65 − 50 = GH₵15.00. Percentage profit = (profit ÷ cost price) × 100 = (15/50) × 100 = 30%. (23.1% wrongly uses the selling price as the base.) Therefore the correct answer is A: 30%.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec');
